package com.primehr.performancemanagement.application;

import com.primehr.config.PrimeHrProperties;import com.primehr.integration.administrative.PermissionDataScope;import com.primehr.performancemanagement.api.PerformanceMonitoringDtos.*;import com.primehr.performancemanagement.domain.*;import com.primehr.performancemanagement.infrastructure.*;import com.primehr.rsp.applicant.storage.DocumentStorage;import com.primehr.shared.audit.PrimeHrAuditService;import com.primehr.shared.exception.*;import org.springframework.security.access.AccessDeniedException;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.multipart.MultipartFile;import java.io.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.time.*;import java.util.*;import java.util.function.Supplier;import java.util.stream.Collectors;

@Service@Transactional public class PerformanceMonitoringServiceImpl implements PerformanceMonitoringService{
 private final PerformanceMonitoringCaseRepository cases;private final PerformanceMonitoringUpdateRepository updates;private final PerformanceMonitoringFeedbackRepository feedback;private final PerformanceMonitoringEvidenceRepository evidence;private final PerformanceMonitoringActionRepository actions;private final PerformanceCommitmentVersionRepository commitments;private final PerformanceCommitmentItemRepository items;private final PerformanceCommitmentRouteRepository routes;private final PerformanceCommitmentRouteStepRepository routeSteps;private final PerformanceCycleMilestoneRepository milestones;private final DocumentStorage storage;private final PrimeHrProperties properties;private final PrimeHrAuditService audit;
 public PerformanceMonitoringServiceImpl(PerformanceMonitoringCaseRepository c,PerformanceMonitoringUpdateRepository u,PerformanceMonitoringFeedbackRepository f,PerformanceMonitoringEvidenceRepository e,PerformanceMonitoringActionRepository a,PerformanceCommitmentVersionRepository cv,PerformanceCommitmentItemRepository i,PerformanceCommitmentRouteRepository r,PerformanceCommitmentRouteStepRepository rs,PerformanceCycleMilestoneRepository m,DocumentStorage s,PrimeHrProperties p,PrimeHrAuditService au){cases=c;updates=u;feedback=f;evidence=e;actions=a;commitments=cv;items=i;routes=r;routeSteps=rs;milestones=m;storage=s;properties=p;audit=au;}

 @Override public CaseResponse open(String agency,String versionId,OpenCaseRequest request,String actor,PermissionDataScope scope,String correlation){var existing=cases.findByAgencyIdAndCommitmentVersionId(agency,versionId);if(existing.isPresent()){access(existing.get(),actor,scope);return response(agency,existing.get());}PerformanceCommitmentVersion v=commitment(agency,versionId);if(v.getStatus()!=PerformanceCommitmentVersion.Status.APPROVED)throw new IllegalArgumentException("Monitoring requires an approved commitment version");PerformanceCommitmentRoute route=routes.findFirstByAgencyIdAndCommitmentVersionIdOrderByRouteRevisionDesc(agency,versionId).filter(x->x.getStatus()==PerformanceCommitmentRoute.Status.COMPLETED).orElseThrow(()->new IllegalArgumentException("Monitoring requires a completed approval route"));PerformanceCommitmentRouteStep supervisor=routeSteps.findByAgencyIdAndRouteIdOrderByLevelAsc(agency,route.getId()).stream().filter(x->x.getActionType()==PerformanceCommitmentRouteStep.ActionType.RECOMMEND).findFirst().orElseGet(()->routeSteps.findByAgencyIdAndRouteIdOrderByLevelAsc(agency,route.getId()).stream().findFirst().orElseThrow(()->new IllegalArgumentException("Approved commitment route has no supervisor")));if(scope!=PermissionDataScope.AGENCY_WIDE&&!v.getOwnerEmployeeNo().equalsIgnoreCase(actor)&&!supervisor.getEmployeeNo().equalsIgnoreCase(actor))throw new AccessDeniedException("Monitoring case is outside the permitted scope");window(agency,v.getCycleId(),PerformanceCycleMilestone.Type.MONITORING_START,PerformanceCycleMilestone.Type.ACCOMPLISHMENT_DUE,request.overrideWindow(),request.reason());PerformanceMonitoringCase value=cases.saveAndFlush(new PerformanceMonitoringCase(agency,v,supervisor.getEmployeeNo(),route.getRouteFingerprint()));record(agency,value.getId(),null,"OPEN_CASE",request.idempotencyKey(),actor,request.reason());CaseResponse after=response(agency,value);audit.record(agency,"OPEN_PERFORMANCE_MONITORING_CASE","SPMS_MONITORING_CASE",value.getId(),1,value.getVersion(),null,after,request.reason(),correlation);return after;}
 @Override@Transactional(readOnly=true)public List<CaseResponse>list(String agency,String actor,PermissionDataScope scope){return cases.findByAgencyIdOrderByCreatedAtDesc(agency).stream().filter(x->visible(x,actor,scope)).map(x->response(agency,x)).toList();}
 @Override@Transactional(readOnly=true)public CaseResponse get(String agency,String id,String actor,PermissionDataScope scope){PerformanceMonitoringCase value=monitoringCase(agency,id);access(value,actor,scope);return response(agency,value);}
 @Override public UpdateResponse addUpdate(String agency,String caseId,UpdateInput input,String actor,PermissionDataScope scope,String correlation){PerformanceMonitoringCase c=monitoringCase(agency,caseId);ownerWrite(c,actor,scope);active(c);PerformanceMonitoringAction prior=actions.findByAgencyIdAndMonitoringCaseIdAndRequestKey(agency,caseId,input.idempotencyKey()).orElse(null);if(prior!=null)return updateResponse(agency,update(agency,prior.getSubjectId()));itemForCase(agency,c,input.commitmentItemId());String root=UUID.randomUUID().toString();PerformanceMonitoringUpdate value=updates.saveAndFlush(new PerformanceMonitoringUpdate(agency,caseId,input.commitmentItemId(),root,1,null,input.reportingDate(),input.narrativeAccomplishment(),input.accomplishedValue(),input.progressPercent(),input.issuesRisks(),input.supportNeeded(),input.employeeRemarks()));record(agency,caseId,value.getId(),"CREATE_UPDATE",input.idempotencyKey(),actor,null);UpdateResponse after=updateResponse(agency,value);audit.record(agency,"CREATE_MONITORING_UPDATE","SPMS_MONITORING_UPDATE",value.getId(),1,value.getVersion(),null,after,null,correlation);return after;}
 @Override public UpdateResponse editUpdate(String agency,String id,UpdateEdit input,String actor,PermissionDataScope scope,String correlation){PerformanceMonitoringUpdate value=update(agency,id);PerformanceMonitoringCase c=monitoringCase(agency,value.getMonitoringCaseId());ownerWrite(c,actor,scope);active(c);check(value.getVersion(),input.recordVersion());UpdateResponse before=updateResponse(agency,value);value.edit(input.reportingDate(),input.narrativeAccomplishment(),input.accomplishedValue(),input.progressPercent(),input.issuesRisks(),input.supportNeeded(),input.employeeRemarks());value=updates.saveAndFlush(value);UpdateResponse after=updateResponse(agency,value);audit.record(agency,"EDIT_MONITORING_UPDATE","SPMS_MONITORING_UPDATE",id,value.getRevisionNo(),value.getVersion(),before,after,null,correlation);return after;}
 @Override public UpdateResponse submitUpdate(String agency,String id,ActionCommand input,String actor,PermissionDataScope scope,String correlation){PerformanceMonitoringUpdate value=update(agency,id);PerformanceMonitoringCase c=monitoringCase(agency,value.getMonitoringCaseId());ownerWrite(c,actor,scope);PerformanceMonitoringAction prior=action(agency,c.getId(),input.idempotencyKey());if(prior!=null)return updateResponse(agency,value);active(c);check(value.getVersion(),input.recordVersion());UpdateResponse before=updateResponse(agency,value);value.submit(actor,Instant.now());value=updates.saveAndFlush(value);record(agency,c.getId(),value.getId(),"SUBMIT_UPDATE",input.idempotencyKey(),actor,input.reason());UpdateResponse after=updateResponse(agency,value);audit.record(agency,"SUBMIT_MONITORING_UPDATE","SPMS_MONITORING_UPDATE",id,value.getRevisionNo(),value.getVersion(),before,after,input.reason(),correlation);return after;}
 @Override public UpdateResponse decideUpdate(String agency,String id,ActionCommand input,String actor,PermissionDataScope scope,boolean accept,String correlation){PerformanceMonitoringUpdate value=update(agency,id);PerformanceMonitoringCase c=monitoringCase(agency,value.getMonitoringCaseId());supervisorWrite(c,actor,scope);PerformanceMonitoringAction prior=action(agency,c.getId(),input.idempotencyKey());if(prior!=null)return updateResponse(agency,value);active(c);check(value.getVersion(),input.recordVersion());if(!accept&&(input.reason()==null||input.reason().isBlank()))throw new IllegalArgumentException("A return reason is required");UpdateResponse before=updateResponse(agency,value);if(accept)value.accept();else value.returned();value=updates.saveAndFlush(value);feedback.saveAndFlush(new PerformanceMonitoringFeedback(agency,id,accept?"ACCEPT":"RETURN",input.reason(),actor,Instant.now()));record(agency,c.getId(),id,accept?"ACCEPT_UPDATE":"RETURN_UPDATE",input.idempotencyKey(),actor,input.reason());UpdateResponse after=updateResponse(agency,value);audit.record(agency,accept?"ACCEPT_MONITORING_UPDATE":"RETURN_MONITORING_UPDATE","SPMS_MONITORING_UPDATE",id,value.getRevisionNo(),value.getVersion(),before,after,input.reason(),correlation);return after;}
 @Override public UpdateResponse correctUpdate(String agency,String id,UpdateInput input,String actor,PermissionDataScope scope,String correlation){PerformanceMonitoringUpdate priorUpdate=update(agency,id);PerformanceMonitoringCase c=monitoringCase(agency,priorUpdate.getMonitoringCaseId());ownerWrite(c,actor,scope);PerformanceMonitoringAction prior=action(agency,c.getId(),input.idempotencyKey());if(prior!=null)return updateResponse(agency,update(agency,prior.getSubjectId()));active(c);if(priorUpdate.getStatus()!=PerformanceMonitoringUpdate.Status.SUBMITTED&&priorUpdate.getStatus()!=PerformanceMonitoringUpdate.Status.ACCEPTED&&priorUpdate.getStatus()!=PerformanceMonitoringUpdate.Status.RETURNED)throw new IllegalStateException("Only submitted monitoring history may be corrected");if(!priorUpdate.getCommitmentItemId().equals(input.commitmentItemId()))throw new IllegalArgumentException("A correction cannot change its commitment item");int revision=updates.findByAgencyIdAndRootUpdateIdOrderByRevisionNoAsc(agency,priorUpdate.getRootUpdateId()).stream().mapToInt(PerformanceMonitoringUpdate::getRevisionNo).max().orElse(0)+1;priorUpdate.supersede();updates.saveAndFlush(priorUpdate);PerformanceMonitoringUpdate value=updates.saveAndFlush(new PerformanceMonitoringUpdate(agency,c.getId(),input.commitmentItemId(),priorUpdate.getRootUpdateId(),revision,priorUpdate.getId(),input.reportingDate(),input.narrativeAccomplishment(),input.accomplishedValue(),input.progressPercent(),input.issuesRisks(),input.supportNeeded(),input.employeeRemarks()));record(agency,c.getId(),value.getId(),"CORRECT_UPDATE",input.idempotencyKey(),actor,null);UpdateResponse after=updateResponse(agency,value);audit.record(agency,"CORRECT_MONITORING_UPDATE","SPMS_MONITORING_UPDATE",value.getId(),revision,value.getVersion(),null,after,null,correlation);return after;}
 @Override public EvidenceResponse uploadEvidence(String agency,String updateId,EvidenceCommand input,MultipartFile file,String actor,PermissionDataScope scope,String correlation){PerformanceMonitoringUpdate update=update(agency,updateId);PerformanceMonitoringCase c=monitoringCase(agency,update.getMonitoringCaseId());ownerWrite(c,actor,scope);active(c);PerformanceMonitoringAction prior=action(agency,c.getId(),input.idempotencyKey());if(prior!=null)return evidenceResponse(evidence(agency,prior.getSubjectId()));if(!properties.storage().enabled())throw new IllegalStateException("Document uploads are disabled");if(file==null||file.isEmpty()||file.getSize()>properties.storage().maximumBytes())throw new IllegalArgumentException("Evidence size is invalid");String media=Objects.requireNonNullElse(file.getContentType(),"");if(!properties.storage().allowedMediaTypes().contains(media))throw new IllegalArgumentException("Evidence media type is not allowed");byte[] bytes;try{bytes=file.getBytes();}catch(IOException e){throw new IllegalArgumentException("Evidence could not be read",e);}verifySignature(media,bytes);String filename=safeFilename(file.getOriginalFilename());PerformanceMonitoringEvidence replaced=null;if(input.replacesEvidenceId()!=null&&!input.replacesEvidenceId().isBlank()){replaced=evidence(agency,input.replacesEvidenceId());if(!replaced.getMonitoringCaseId().equals(c.getId())||replaced.getStatus()!=PerformanceMonitoringEvidence.Status.ACTIVE)throw new IllegalArgumentException("Replacement evidence must be active in the same monitoring case");}String key=agency+"/performance-monitoring/"+c.getId()+"/"+UUID.randomUUID().toString().replace("-","");storage.put(key,bytes,media);try{PerformanceMonitoringEvidence value=evidence.saveAndFlush(new PerformanceMonitoringEvidence(agency,c.getId(),updateId,update.getCommitmentItemId(),filename,storage.provider(),key,media,bytes.length,sha256(bytes),normalizeConfidentiality(input.confidentiality()),replaced==null?null:replaced.getId(),actor,Instant.now()));if(replaced!=null){replaced.supersede();evidence.saveAndFlush(replaced);}record(agency,c.getId(),value.getId(),"UPLOAD_EVIDENCE",input.idempotencyKey(),actor,null);EvidenceResponse after=evidenceResponse(value);audit.record(agency,"UPLOAD_MONITORING_EVIDENCE","SPMS_MONITORING_EVIDENCE",value.getId(),null,value.getVersion(),null,after,null,correlation);return after;}catch(RuntimeException ex){storage.delete(key);throw ex;}}
 @Override public EvidenceContent downloadEvidence(String agency,String id,String actor,PermissionDataScope scope,String correlation){PerformanceMonitoringEvidence value=evidence(agency,id);PerformanceMonitoringCase c=monitoringCase(agency,value.getMonitoringCaseId());access(c,actor,scope);if(value.getStatus()==PerformanceMonitoringEvidence.Status.VOIDED)throw new IllegalStateException("Voided evidence is not downloadable");audit.record(agency,"DOWNLOAD_MONITORING_EVIDENCE","SPMS_MONITORING_EVIDENCE",id,null,value.getVersion(),null,Map.of("caseId",c.getId(),"checksum",value.getChecksum()),null,correlation);return new EvidenceContent(value.getOriginalFilename(),value.getMediaType(),value.getByteSize(),storage.get(value.getStorageObjectKey()));}
 @Override public EvidenceResponse voidEvidence(String agency,String id,ActionCommand input,String actor,PermissionDataScope scope,String correlation){PerformanceMonitoringEvidence value=evidence(agency,id);PerformanceMonitoringCase c=monitoringCase(agency,value.getMonitoringCaseId());ownerWrite(c,actor,scope);PerformanceMonitoringAction prior=action(agency,c.getId(),input.idempotencyKey());if(prior!=null)return evidenceResponse(value);active(c);check(value.getVersion(),input.recordVersion());EvidenceResponse before=evidenceResponse(value);value.voided(input.reason());value=evidence.saveAndFlush(value);record(agency,c.getId(),id,"VOID_EVIDENCE",input.idempotencyKey(),actor,input.reason());EvidenceResponse after=evidenceResponse(value);audit.record(agency,"VOID_MONITORING_EVIDENCE","SPMS_MONITORING_EVIDENCE",id,null,value.getVersion(),before,after,input.reason(),correlation);return after;}
 @Override public CaseResponse submitAccomplishments(String agency,String id,ActionCommand input,String actor,PermissionDataScope scope,String correlation){PerformanceMonitoringCase c=monitoringCase(agency,id);ownerWrite(c,actor,scope);if(action(agency,id,input.idempotencyKey())!=null)return response(agency,c);check(c.getVersion(),input.recordVersion());window(agency,c.getCycleId(),PerformanceCycleMilestone.Type.MONITORING_START,PerformanceCycleMilestone.Type.ACCOMPLISHMENT_DUE,input.overrideWindow(),input.reason());readiness(agency,c);CaseResponse before=response(agency,c);c.submitAccomplishment(actor,Instant.now());c=cases.saveAndFlush(c);record(agency,id,id,"SUBMIT_ACCOMPLISHMENTS",input.idempotencyKey(),actor,input.reason());CaseResponse after=response(agency,c);audit.record(agency,"SUBMIT_MONITORING_ACCOMPLISHMENTS","SPMS_MONITORING_CASE",id,c.getAccomplishmentRevision(),c.getVersion(),before,after,input.reason(),correlation);return after;}
 @Override public CaseResponse returnAccomplishments(String agency,String id,ActionCommand input,String actor,PermissionDataScope scope,String correlation){PerformanceMonitoringCase c=monitoringCase(agency,id);supervisorWrite(c,actor,scope);if(action(agency,id,input.idempotencyKey())!=null)return response(agency,c);check(c.getVersion(),input.recordVersion());CaseResponse before=response(agency,c);c.returnAccomplishment(input.reason());c=cases.saveAndFlush(c);record(agency,id,id,"RETURN_ACCOMPLISHMENTS",input.idempotencyKey(),actor,input.reason());CaseResponse after=response(agency,c);audit.record(agency,"RETURN_MONITORING_ACCOMPLISHMENTS","SPMS_MONITORING_CASE",id,c.getAccomplishmentRevision(),c.getVersion(),before,after,input.reason(),correlation);return after;}

 private void readiness(String agency,PerformanceMonitoringCase c){List<PerformanceCommitmentItem> required=items.findByAgencyIdAndCommitmentVersionIdOrderByCommitmentSectionIdAscDisplayOrderAsc(agency,c.getCommitmentVersionId()).stream().filter(PerformanceCommitmentItem::isRequired).toList();List<PerformanceMonitoringUpdate> history=updates.findByAgencyIdAndMonitoringCaseIdOrderByCreatedAtAsc(agency,c.getId());for(PerformanceCommitmentItem item:required){List<PerformanceMonitoringUpdate> current=history.stream().filter(x->x.getCommitmentItemId().equals(item.getId())&&x.getStatus()!=PerformanceMonitoringUpdate.Status.SUPERSEDED&&x.getStatus()!=PerformanceMonitoringUpdate.Status.VOIDED).toList();if(current.isEmpty()||current.stream().anyMatch(x->x.getStatus()==PerformanceMonitoringUpdate.Status.DRAFT||x.getStatus()==PerformanceMonitoringUpdate.Status.RETURNED))throw new IllegalArgumentException(item.getLabel()+": a submitted progress/accomplishment update is required");if(item.isSourceRequiresEvidence()&&evidence.findByAgencyIdAndMonitoringCaseIdOrderByUploadedAtAsc(agency,c.getId()).stream().noneMatch(x->x.getCommitmentItemId().equals(item.getId())&&x.getStatus()==PerformanceMonitoringEvidence.Status.ACTIVE))throw new IllegalArgumentException(item.getLabel()+": required evidence is missing");}}
 private void window(String agency,String cycle,PerformanceCycleMilestone.Type startType,PerformanceCycleMilestone.Type dueType,boolean override,String reason){Instant now=Instant.now();var values=milestones.findByAgencyIdAndCycleIdOrderByDisplayOrderAsc(agency,cycle);PerformanceCycleMilestone start=values.stream().filter(x->x.getType()==startType).findFirst().orElseThrow(()->new IllegalArgumentException(startType+" milestone is required"));PerformanceCycleMilestone due=values.stream().filter(x->x.getType()==dueType).findFirst().orElseThrow(()->new IllegalArgumentException(dueType+" milestone is required"));Instant end=due.getEndsAt()==null?due.getStartsAt():due.getEndsAt();if((now.isBefore(start.getStartsAt())||now.isAfter(end))&&!override)throw new IllegalArgumentException("Performance monitoring is outside the configured cycle window");if(override&&(reason==null||reason.isBlank()))throw new IllegalArgumentException("A window override reason is required");}
 private PerformanceCommitmentItem itemForCase(String agency,PerformanceMonitoringCase c,String itemId){PerformanceCommitmentItem item=items.findById(itemId).filter(x->x.getAgencyId().equals(agency)&&x.getCommitmentVersionId().equals(c.getCommitmentVersionId())).orElseThrow(()->new ResourceNotFoundException("Commitment item not found in monitoring case"));return item;}
 private void active(PerformanceMonitoringCase c){if(c.getStatus()!=PerformanceMonitoringCase.Status.OPEN&&c.getStatus()!=PerformanceMonitoringCase.Status.RETURNED)throw new IllegalStateException("Monitoring case is not editable");}
 private void ownerWrite(PerformanceMonitoringCase c,String actor,PermissionDataScope scope){if(scope!=PermissionDataScope.AGENCY_WIDE&&!c.getOwnerEmployeeNo().equalsIgnoreCase(actor))throw new AccessDeniedException("Only the monitoring owner may perform this action");}
 private void supervisorWrite(PerformanceMonitoringCase c,String actor,PermissionDataScope scope){if(scope!=PermissionDataScope.AGENCY_WIDE&&!c.getSupervisorEmployeeNo().equalsIgnoreCase(actor))throw new AccessDeniedException("Only the assigned supervisor may perform this action");}
 private boolean visible(PerformanceMonitoringCase c,String actor,PermissionDataScope scope){return scope==PermissionDataScope.AGENCY_WIDE||scope==PermissionDataScope.OWN_RECORDS&&c.getOwnerEmployeeNo().equalsIgnoreCase(actor)||scope==PermissionDataScope.ASSIGNED_RECORDS&&c.getSupervisorEmployeeNo().equalsIgnoreCase(actor);}
 private void access(PerformanceMonitoringCase c,String actor,PermissionDataScope scope){if(!visible(c,actor,scope))throw new AccessDeniedException("Monitoring case is outside the permitted scope");}
 private PerformanceMonitoringCase monitoringCase(String a,String id){return cases.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("Performance monitoring case not found"));}private PerformanceMonitoringUpdate update(String a,String id){return updates.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("Performance monitoring update not found"));}private PerformanceMonitoringEvidence evidence(String a,String id){return evidence.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("Performance monitoring evidence not found"));}private PerformanceCommitmentVersion commitment(String a,String id){return commitments.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("Performance commitment version not found"));}
 private PerformanceMonitoringAction action(String a,String c,String key){return actions.findByAgencyIdAndMonitoringCaseIdAndRequestKey(a,c,key).orElse(null);}private void record(String a,String c,String subject,String type,String key,String actor,String reason){actions.saveAndFlush(new PerformanceMonitoringAction(a,c,subject,type,key,actor,reason,Instant.now()));}
 private CaseResponse response(String agency,PerformanceMonitoringCase c){List<PerformanceMonitoringEvidence> ev=evidence.findByAgencyIdAndMonitoringCaseIdOrderByUploadedAtAsc(agency,c.getId());Map<String,List<PerformanceMonitoringEvidence>> byUpdate=ev.stream().collect(Collectors.groupingBy(PerformanceMonitoringEvidence::getMonitoringUpdateId));List<PerformanceMonitoringUpdate> us=updates.findByAgencyIdAndMonitoringCaseIdOrderByCreatedAtAsc(agency,c.getId());List<String> ids=us.stream().map(PerformanceMonitoringUpdate::getId).toList();Map<String,List<PerformanceMonitoringFeedback>> fb=ids.isEmpty()?Map.of():feedback.findByAgencyIdAndMonitoringUpdateIdInOrderByActedAtAsc(agency,ids).stream().collect(Collectors.groupingBy(PerformanceMonitoringFeedback::getMonitoringUpdateId));List<CaseItemResponse> caseItems=items.findByAgencyIdAndCommitmentVersionIdOrderByCommitmentSectionIdAscDisplayOrderAsc(agency,c.getCommitmentVersionId()).stream().map(x->new CaseItemResponse(x.getId(),x.getLabel(),x.getOutputDescription(),x.getPerformanceIndicator(),x.getUnitOfMeasure(),x.getWeightPercent(),x.isRequired(),x.isSourceRequiresEvidence(),x.getSourceEvidenceRequirement(),x.getCommittedValue(),x.getCommittedFrom(),x.getCommittedTo(),x.getTargetStart(),x.getTargetEnd(),x.getDisplayOrder())).toList();return new CaseResponse(c.getId(),c.getCommitmentVersionId(),c.getCycleId(),c.getPolicyVersionId(),c.getFormType(),c.getOwnerEmployeeId(),c.getOwnerEmployeeNo(),c.getOwnerName(),c.getBusinessUnitId(),c.getSupervisorEmployeeNo(),c.getRouteFingerprint(),c.getCommitmentFingerprint(),c.getStatus().name(),c.getAccomplishmentRevision(),c.getAccomplishmentSubmittedBy(),c.getAccomplishmentSubmittedAt(),c.getReturnReason(),c.getVersion(),caseItems,us.stream().map(x->updateResponse(x,fb.getOrDefault(x.getId(),List.of()),byUpdate.getOrDefault(x.getId(),List.of()))).toList(),ev.stream().map(this::evidenceResponse).toList());}
 private UpdateResponse updateResponse(String agency,PerformanceMonitoringUpdate u){return updateResponse(u,feedback.findByAgencyIdAndMonitoringUpdateIdOrderByActedAtAsc(agency,u.getId()),evidence.findByAgencyIdAndMonitoringCaseIdOrderByUploadedAtAsc(agency,u.getMonitoringCaseId()).stream().filter(x->x.getMonitoringUpdateId().equals(u.getId())).toList());}
 private UpdateResponse updateResponse(PerformanceMonitoringUpdate u,List<PerformanceMonitoringFeedback> fb,List<PerformanceMonitoringEvidence> ev){return new UpdateResponse(u.getId(),u.getCommitmentItemId(),u.getRootUpdateId(),u.getRevisionNo(),u.getSupersedesId(),u.getReportingDate(),u.getNarrativeAccomplishment(),u.getAccomplishedValue(),u.getProgressPercent(),u.getIssuesRisks(),u.getSupportNeeded(),u.getEmployeeRemarks(),u.getStatus().name(),u.getSubmittedBy(),u.getSubmittedAt(),u.getVersion(),fb.stream().map(x->new FeedbackResponse(x.getId(),x.getDecision(),x.getFeedback(),x.getActorEmployeeNo(),x.getActedAt())).toList(),ev.stream().map(this::evidenceResponse).toList());}
 private EvidenceResponse evidenceResponse(PerformanceMonitoringEvidence e){return new EvidenceResponse(e.getId(),e.getMonitoringUpdateId(),e.getCommitmentItemId(),e.getOriginalFilename(),e.getMediaType(),e.getByteSize(),e.getChecksum(),e.getConfidentiality(),e.getSupersedesId(),e.getStatus().name(),e.getVoidReason(),e.getUploadedBy(),e.getUploadedAt(),e.getVersion());}
 private static void check(long actual,Long expected){if(expected==null||actual!=expected)throw new OptimisticConflictException("Expected recordVersion "+expected+" but current version is "+actual);}private static String normalizeConfidentiality(String value){String v=value==null||value.isBlank()?"SENSITIVE":value.trim().toUpperCase(Locale.ROOT);if(!Set.of("INTERNAL","SENSITIVE").contains(v))throw new IllegalArgumentException("Evidence confidentiality must be INTERNAL or SENSITIVE");return v;}private static String safeFilename(String value){String v=value==null?"evidence":value.replace('\\','/');v=v.substring(v.lastIndexOf('/')+1).replaceAll("[^A-Za-z0-9._ -]","_").trim();return v.isBlank()?"evidence":v.substring(0,Math.min(v.length(),255));}private static String sha256(byte[] bytes){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}private static void verifySignature(String media,byte[] b){boolean ok=switch(media){case "application/pdf"->b.length>=5&&new String(b,0,5,StandardCharsets.US_ASCII).equals("%PDF-");case "image/png"->b.length>=8&&(b[0]&255)==137&&b[1]==80&&b[2]==78&&b[3]==71;case "image/jpeg"->b.length>=3&&(b[0]&255)==255&&(b[1]&255)==216&&(b[2]&255)==255;default->false;};if(!ok)throw new IllegalArgumentException("Evidence content does not match its media type");}
}
